import{d as s,C as t,o as d,c as p,E as i,a3 as a}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"大壮卦","description":"雷天大壮，震 ☳ 乾 ☰——刚以动，故壮","frontmatter":{"title":"大壮卦","description":"雷天大壮，震 ☳ 乾 ☰——刚以动，故壮","category":"hexagram","aliases":["大壮","雷天大壮"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/34-leitiandazhuang.md","filePath":"yijing/hexagrams/34-leitiandazhuang.md","lastUpdated":1792641266000}'),h={name:"yijing/hexagrams/34-leitiandazhuang.md"},x=s({...h,setup(u){const o=[{id:"zhuang",term:"壮",pinyin:"zhuàng",meaning:"壮盛、强盛。乾刚在下、震动在上，刚以动，故为「大壮」。"},{id:"lizhen",term:"利贞",pinyin:"lì zhēn",meaning:"利于守正。势盛之时，唯一要做的功课就是「守」。"},{id:"dazheng",term:"大者正也",pinyin:"dà zhě zhèng yě",meaning:"大者以正为本。彖传：「大壮利贞，大者正也。」",context:"「正」是天地之道的客观状态，「贞」是人身处其中时的主观选择。"},{id:"zhuangyuzhi",term:"壮于趾",pinyin:"zhuàng yú zhǐ",meaning:"力量刚起就急着迈脚。趾：脚趾，喻行动之初。",context:"初九。势头刚冒头就急着证明自己。"},{id:"zhengxiong",term:"征凶",pinyin:"zhēng xiōng",meaning:"前往则凶。征：往、行。"},{id:"youfu",term:"有孚",pinyin:"yǒu fú",meaning:"有诚信、有信实。孚：信。"},{id:"yongzhuang",term:"用壮",pinyin:"yòng zhuàng",meaning:"一味用刚猛之力硬来。小人的做法。"},{id:"yongwang",term:"用罔",pinyin:"yòng wǎng",meaning:"用「罔」——不显之力。不是没有力量，是有力量而不炫耀、不硬碰。罔：无、不可见。",context:"九三。力量成熟的第一次转折。"},{id:"zhenli",term:"贞厉",pinyin:"zhēn lì",meaning:"守正而仍有危险。厉：危险、戒惧。"},{id:"diyang",term:"羝羊",pinyin:"dī yáng",meaning:"公羊。公羊性喜抵撞，此处喻一味硬冲的刚壮。"},{id:"chufan",term:"触藩",pinyin:"chù fān",meaning:"冲撞篱笆。藩：篱笆、屏障，喻界限与阻碍。"},{id:"leiqijiao",term:"羸其角",pinyin:"léi qí jiǎo",meaning:"角被卡住、缠住。羸：缠绕、毁坏。"},{id:"fanjue",term:"藩决不羸",pinyin:"fān jué bù léi",meaning:"篱笆冲开了，角不再被卡。决：开、裂。"},{id:"dayuzhifu",term:"大舆之輹",pinyin:"dà yú zhī fù",meaning:"大车的车伏兔（车轴部件），承载全车重量。輹：车伏兔。",context:"九四。力量从「角」（冲撞）转为「輹」（承载）。"},{id:"sangyang",term:"丧羊于易",pinyin:"sàng yáng yú yì",meaning:"在平易从容中放下了羊（壮盛之力）。易：平易、从容不费力。",context:"六五。不是守不住才丢，是主动卸力。"},{id:"wuyouli",term:"无攸利",pinyin:"wú yōu lì",meaning:"无所利。攸：所。"},{id:"jiangzeji",term:"艰则吉",pinyin:"jiān zé jí",meaning:"以「艰」——戒惧、如临深渊的谨慎——应对，则吉。",context:"上六。不蛮撞，也谈不上从容，只剩谨慎这一条出路。"},{id:"feilifu",term:"非礼弗履",pinyin:"fēi lǐ fú lǚ",meaning:"不合礼的事不去做。履：践、行。象传语。",context:"大壮之势最易越界，故以「非礼弗履」为戒。"}],e=[{position:"初九",type:"yang",text:"壮于趾，征凶，有孚。",xiang:"壮于趾，其孚穷也。",textModern:"势头刚冒头就急着迈脚，前往必凶——纵有诚信也无济于事。",xiangModern:"强在脚趾上，它的诚信也走到穷尽了：时位不配，力越盛越窘。"},{position:"九二",type:"yang",text:"贞吉。",xiang:"九二贞吉，以中也。",textModern:"守正则吉。",xiangModern:"九二守正而吉，因为它居下卦之中——中比正更要紧。"},{position:"九三",type:"yang",text:"小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。",xiang:"小人用壮，君子罔也。",textModern:"小人一味用刚猛，君子用不显之力；守正仍有危险——像公羊冲撞篱笆，角被卡住。",xiangModern:"小人用壮，君子用罔——同样有力，用法不同，结局也不同。"},{position:"九四",type:"yang",text:"贞吉悔亡，藩决不羸，壮于大舆之輹。",xiang:"藩决不羸，尚往也。",textModern:"守正得吉、悔恨消失；篱笆冲开了不再卡角，力量体现在大车的车轴上。",xiangModern:"篱笆已开、不复被卡，正宜前往——所凭的是承载之力，不是冲撞之力。"},{position:"六五",type:"yin",text:"丧羊于易，无悔。",xiang:"丧羊于易，位不当也。",textModern:"在从容平易中放下了羊，没有悔恨。",xiangModern:"以阴居五，位本不当；但主动卸力、不与势争，故无悔。"},{position:"上六",type:"yin",text:"羝羊触藩，不能退，不能遂，无攸利，艰则吉。",xiang:"不能退不能遂，不详也。艰则吉，咎不长也。",textModern:"公羊再冲篱笆，退不回去、也冲不破，无所利；唯有以戒惧之心去化解，才吉。",xiangModern:"不能退也不能遂，是审察不详；以艰慎应之则吉，因为咎害不会长久。"}];return(m,n)=>{const r=t("DaoHexagramViewer"),l=t("DaoHexagramYaoCards"),g=t("DaoKeywordCards");return d(),p("div",null,[i(r,{name:"大壮",fullName:"雷天大壮",upper:"☳",lower:"☰",guaCi:"大壮，利贞。",pinyin:["dà","zhuàng"],element:"土",direction:"西南",virtue:"壮",insight:"雷在天上，刚以动；壮不在力盛，而在势盛时仍能守住那个正。",guaSlug:"34leitiandazhuang",lines:e}),n[0]||(n[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>雷在天上，大壮。君子以非礼弗履。</p><p>雷在天上：雷本在天下，如今动于天上——其声震四野，其势不可挡，这是大壮之象。君子由此领悟：<strong>不合礼的事，一步也不去踏。</strong></p><p>「非礼弗履」——<strong>履</strong>是践、是行。大壮之世最不缺的就是力，最难的是<strong>有力而不越界</strong>。势盛时人最容易默认「我有能力，所以我有资格」，而这一句正是把这种默认按住：力是力，分是分。</p><p>分形结构：</p><ul><li>雷（震）→ 动：势已发动，声威远播，不可遏止</li><li>天（乾）→ 刚：刚健在上，是这声响的底气与根基</li></ul><p>势盛而能自守，才是真的壮。若仗着盛势去蹚不该蹚的线，那雷声再大，也只是九三那只卡住角的公羊。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>大壮，大者壮也。刚以动，故壮。大壮利贞，大者正也。正大而天地之情可见矣。</p><p>逐句释义：</p><ul><li><strong>大壮，大者壮也</strong> —— 所谓大壮，是「大」者壮盛：阳刚之势盛大，故称大壮。</li><li><strong>刚以动，故壮</strong> —— 刚健而又能发动，所以壮。刚是底气，动是发用；有刚无动则滞，有动无刚则浮。</li><li><strong>大壮利贞，大者正也</strong> —— 大壮宜于守正，因为「大」本身就该以正为本。壮而不正，只是力大。</li><li><strong>正大而天地之情可见矣</strong> —— 能正而且大，天地之情就由此显现了。</li></ul><blockquote><p><strong>「正」与「贞」的分野</strong>： <strong>正</strong>是天地之道的客观状态——万物各得其所，是雷动天上的自然节奏，是乾刚之气本来的样子，是「天地的实情」。 <strong>贞</strong>是人身处这种势中时的主观选择——因为人有了异心、有了欲、有了可仗之势，才必须靠「守」这个动作，把自己的行为强行校准回正的轨道。</p><p>彖传那句话的分量在这里：人若能在势不可挡的时刻，仍以「贞」守住那个「正」，人就与天地同频了。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"土",guaSlug:"34leitiandazhuang",glossary:o,items:e}),n[1]||(n[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初九-·-壮于趾-征凶-有孚" tabindex="-1">初九 · 壮于趾，征凶，有孚 <a class="header-anchor" href="#初九-·-壮于趾-征凶-有孚" aria-label="Permalink to &quot;初九 · 壮于趾，征凶，有孚&quot;">​</a></h3><ul><li><strong>壮于趾</strong> → 力量刚起，就先冒在脚上</li><li><strong>征凶</strong> → 前往则凶</li><li><strong>有孚</strong> → 有诚信、有信实</li></ul><p>初九是全卦力量的起点，也最容易因为「有力」而急着证明自己。爻辞的判断很干脆：征凶——该静的时候动了。不是能力不足，而是时位不对却硬要用。</p><p>象曰「壮于趾，其孚穷也」：力都堆在脚趾上，连那点诚信也走到穷尽了。<strong>藏器待时</strong>——势头刚起，还不是行动的时刻。</p><blockquote><p>核心洞见：初九之凶，不在「壮」，在「急于用」。</p></blockquote><h3 id="九二-·-贞吉" tabindex="-1">九二 · 贞吉 <a class="header-anchor" href="#九二-·-贞吉" aria-label="Permalink to &quot;九二 · 贞吉&quot;">​</a></h3><ul><li><strong>贞吉</strong> → 守正则吉</li></ul><p>九二阳居阴位，位不当，却居下卦之中。爻辞只给两个字：贞吉。</p><p>象曰「九二贞吉，以中也」——<strong>中比正更要紧</strong>。位置不完全「正确」并不致命，只要守住中道：用力不过、不偏、恰如其分。这是大壮卦第一次给出的「正确用力」范本。</p><blockquote><p>核心洞见：位不当而能守中，依然吉。中，是比正更基础的功课。</p></blockquote><h3 id="九三-·-小人用壮-君子用罔-贞厉。羝羊触藩-羸其角" tabindex="-1">九三 · 小人用壮，君子用罔，贞厉。羝羊触藩，羸其角 <a class="header-anchor" href="#九三-·-小人用壮-君子用罔-贞厉。羝羊触藩-羸其角" aria-label="Permalink to &quot;九三 · 小人用壮，君子用罔，贞厉。羝羊触藩，羸其角&quot;">​</a></h3><ul><li><strong>用壮</strong> → 一味用刚猛硬撞</li><li><strong>用罔</strong> → 用不显之力（罔：无、不可见）</li><li><strong>羝羊触藩，羸其角</strong> → 公羊冲撞篱笆，角被卡住缠住</li></ul><p>来到下卦最上位，力量到了临界点。小人在这个位置会一味用刚猛（用壮），君子则懂得用「罔」——<strong>不是没有力量，是有力量而不炫耀、不硬碰</strong>。</p><p>象曰「小人用壮，君子罔也」：同样的力，两样用法。这是力量成熟道路上<strong>第一次真正的转折</strong>，也是全卦最危险的一爻之一：临界之凶。</p><blockquote><p>核心洞见：罔，是不显之力。懂得把力收起来，才算开始会用力量。</p></blockquote><h3 id="九四-·-贞吉悔亡-藩决不羸-壮于大舆之輹" tabindex="-1">九四 · 贞吉悔亡，藩决不羸，壮于大舆之輹 <a class="header-anchor" href="#九四-·-贞吉悔亡-藩决不羸-壮于大舆之輹" aria-label="Permalink to &quot;九四 · 贞吉悔亡，藩决不羸，壮于大舆之輹&quot;">​</a></h3><ul><li><strong>藩决不羸</strong> → 篱笆冲开了，角不再被卡</li><li><strong>壮于大舆之輹</strong> → 力体现在大车的车伏兔上</li></ul><p>跨过临界，进入上卦，来到新的阶位。篱笆不再卡住（决），力量也不再体现为「角」（冲撞），而体现为「輹」（车伏兔——承载与运行之力）。</p><p>象曰「藩决不羸，尚往也」：该往前了。但所凭的不再是冲撞，是承载。<strong>用变了，吉从此来</strong>——这是全卦一次质的跃升：力量从「对抗式的冲撞」转化为「承载式的运行」。</p><blockquote><p>核心洞见：从「角」到「輹」，是力量成熟最关键的一次转化。</p></blockquote><h3 id="六五-·-丧羊于易-无悔" tabindex="-1">六五 · 丧羊于易，无悔 <a class="header-anchor" href="#六五-·-丧羊于易-无悔" aria-label="Permalink to &quot;六五 · 丧羊于易，无悔&quot;">​</a></h3><ul><li><strong>丧羊于易</strong> → 在平易从容中放下了羊（壮盛之力）</li><li><strong>无悔</strong> → 没有悔恨</li></ul><p>六五以阴居五（君位），位不当，却与九二相应。此爻讲的是：<strong>主动放下羊</strong>——放下力量、放下群羊所代表的壮盛——却没有后悔。</p><p>象曰点明「位不当也」：位确实不当，可结果是无悔。因为这不是「守不住」才丢，是<strong>主动、从容地卸力</strong>——她懂得势已经到了不需要再证明、不必再硬撑的阶段。「易」正是这份从容、不费力、恰到好处的放手。</p><blockquote><p>核心洞见：放下比守住更难，也更高。这是全卦境界最高的一爻。</p></blockquote><h3 id="上六-·-羝羊触藩-不能退-不能遂-无攸利-艰则吉" tabindex="-1">上六 · 羝羊触藩，不能退，不能遂，无攸利，艰则吉 <a class="header-anchor" href="#上六-·-羝羊触藩-不能退-不能遂-无攸利-艰则吉" aria-label="Permalink to &quot;上六 · 羝羊触藩，不能退，不能遂，无攸利，艰则吉&quot;">​</a></h3><ul><li><strong>不能退，不能遂</strong> → 退不回，也冲不破（遂：顺利冲破、达成）</li><li><strong>无攸利</strong> → 无所利</li><li><strong>艰则吉</strong> → 以戒惧之心应对，则吉</li></ul><p>全卦最顶端，震（动）到了极点却还不知道停。公羊又一次冲向藩篱，这次卡得更死：两条路都被堵住。</p><p>这里藏着一层轻微的警诫——不是道德批判，而是<strong>结构上的滞后</strong>：六五在还没到顶时就懂得卸力，上六却一路带着九三那套已经证明会「羸其角」的老办法冲到了尽头。「时」已经走到终点，「用」却还停在起点的惯性里。</p><p>「艰则吉」的落点，不是「退无可退只好硬撑，歪打正着地吉」，而是——当事人终于在这个卡死的处境里生出了「艰」这个心态：不再蛮撞（九三的老路已被证明失败），也谈不上从容放下（六五的境界此刻已经来不及），而是带着戒惧、如临深渊，一点一点去化解这个卡住的局。<strong>艰，是这一爻唯一剩下的出路，也恰恰是这条出路让它转吉。</strong></p><p>象曰「不能退不能遂，不详也。艰则吉，咎不长也」：卡住的原因是审察不详；而一旦以艰慎处之，咎害便不会长。</p><blockquote><p>核心洞见：敬慎是最后一道保险——它不是本事，是本事都已用尽之后，唯一还管用的态度。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',34)),i(g,{title:"字词释义",items:[{term:"壮",pinyin:["zhuàng"],meaning:"壮盛、强盛。刚以动，故壮。"},{term:"利贞",pinyin:["lì","zhēn"],meaning:"利于守正。势盛之时，功课全在一个「守」字。"},{term:"壮于趾",pinyin:["zhuàng","yú","zhǐ"],meaning:"力量刚起就冒在脚上。趾：脚趾。"},{term:"征凶",pinyin:["zhēng","xiōng"],meaning:"前往则凶。征：往、行。"},{term:"有孚",pinyin:["yǒu","fú"],meaning:"有诚信、有信实。孚：信。"},{term:"用壮",pinyin:["yòng","zhuàng"],meaning:"一味用刚猛之力硬来。"},{term:"用罔",pinyin:["yòng","wǎng"],meaning:"用不显之力。有力量而不炫耀、不硬碰。罔：无、不可见。"},{term:"贞厉",pinyin:["zhēn","lì"],meaning:"守正而仍有危险。厉：危险、戒惧。"},{term:"羝羊",pinyin:["dī","yáng"],meaning:"公羊。性喜抵撞，喻一味硬冲的刚壮。"},{term:"触藩",pinyin:["chù","fān"],meaning:"冲撞篱笆。藩：篱笆、屏障，喻界限。"},{term:"羸其角",pinyin:["léi","qí","jiǎo"],meaning:"角被卡住、缠住。羸：缠绕、毁坏。"},{term:"藩决不羸",pinyin:["fān","jué","bù","léi"],meaning:"篱笆冲开了，角不再被卡。决：开、裂。"},{term:"大舆之輹",pinyin:["dà","yú","zhī","fù"],meaning:"大车的车伏兔，承载全车之重。喻承载之力。"},{term:"丧羊于易",pinyin:["sàng","yáng","yú","yì"],meaning:"在平易从容中放下壮盛之力。易：平易、不费力。"},{term:"艰则吉",pinyin:["jiān","zé","jí"],meaning:"以戒惧如临深渊之心应对，则吉。"},{term:"非礼弗履",pinyin:["fēi","lǐ","fú","lǚ"],meaning:"不合礼的事一步不踏。履：践、行。"},{term:"大者正也",pinyin:["dà","zhě","zhèng","yě"],meaning:"大者以正为本。壮而不正，只是力大。"}]}),n[2]||(n[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>大壮是<strong>力量成熟史</strong>。震上乾下，刚健在下而发动于上，其势盛大——这是「壮」；但卦辞只有两个字的要求：<strong>利贞</strong>。</p><p>六爻讲的是同一种力量，在六个不同时位上的六种用法：</p><ul><li>初九：想用（壮于趾，征凶）</li><li>九二：会用（贞吉，以中）</li><li>九三：用壮还是用罔（小人用壮，君子用罔）</li><li>九四：从冲撞转为承载（壮于大舆之輹）</li><li>六五：不必用（丧羊于易，无悔）</li><li>上六：忘了停（不能退，不能遂，艰则吉）</li></ul><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p><strong>它问的从来不是「要不要有力量」，而是「此刻该怎么做」。</strong></p><p>这是大壮最锋利的一句话：易经六十四卦几乎从不停在「存在论式的自我认同」上，它永远在问此刻该怎么做。力量本身没有善恶，用的方式和时机才决定吉凶。</p><p>三个层次：</p><ol><li><strong>力之辨</strong> —— 同样刚壮，用壮与用罔是两条路（九三）</li><li><strong>用之转</strong> —— 从「角」（冲撞）到「輹」（承载），是力量成熟最关键的一次转化（九四）</li><li><strong>势之收</strong> —— 六五的「主动放下」与上六的「被动卡死后靠艰慎化解」，是全卦最深的一组对照：<strong>懂得提前放下，永远比在极限处狼狈补救更高明</strong></li></ol><p>而贯穿始终的是那个「贞」：正因为人有力、有欲、有势，才必须靠守的动作，把自己校准回「正」的轨道。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li><strong>先分「壮于趾」与「贞吉」</strong>：刚有一点成绩、资源、话语权时，急着证明自己（征凶），还是先守中（贞吉）？</li><li><strong>练「用罔」</strong>：有能力而不炫耀、不硬碰——不是藏拙，是不把力气花在不该花的地方</li><li><strong>主动把「角」换成「輹」</strong>：从靠冲撞推进，转为靠承载、靠运行、靠把事托住</li><li><strong>在到顶之前学会卸力</strong>：六五的「丧羊于易」提示——卸力要趁早、要从容，等到退无可退时就只剩「艰」了</li><li><strong>留住「艰」这个态度</strong>：卡死的局面里，唯一管用的往往不是更用力，而是更戒惧</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>大壮卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞关键词</th><th>力量状态</th><th>核心教训</th></tr></thead><tbody><tr><td>卦辞</td><td>大壮，利贞</td><td>势盛而欲动</td><td>势盛时的功课是守</td></tr><tr><td>初九</td><td>壮于趾，征凶</td><td>力刚起，冒进</td><td>藏器待时</td></tr><tr><td>九二</td><td>贞吉</td><td>不当位而得中</td><td>中比正更要紧</td></tr><tr><td>九三</td><td>用壮／用罔，羸其角</td><td>临界之凶</td><td>罔是不显之力</td></tr><tr><td>九四</td><td>藩决不羸，壮于大舆之輹</td><td>冲撞化承载</td><td>用变了，吉从此来</td></tr><tr><td>六五</td><td>丧羊于易，无悔</td><td>主动卸力</td><td>放下比守住更难</td></tr><tr><td>上六</td><td>羝羊触藩，艰则吉</td><td>动极忘停</td><td>敬慎是最后一道保险</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>力量本身没有善恶</strong>——用的方式和时机才决定吉凶</li><li><strong>「中」先于「正」</strong>——九二位不当而贞吉，因为守中</li><li><strong>从「角」到「輹」</strong>——力量成熟最关键的一次转化：从对抗式冲撞，到承载式运行</li><li><strong>卸力要趁早</strong>——六五在未到顶时从容放下，故无悔</li><li><strong>敬慎是最后一道保险</strong>——上六卡死之后，剩下的出路是「艰」</li><li><strong>提前放下 ＞ 极限补救</strong>——六五与上六的对照，是整卦最深的一组</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>读大壮卦，我改掉了一个默认反应：<strong>不停在「接受自己是什么」，而是永远在问「此刻该怎么做」。</strong></p><p>这是整卦留给我最锋利的一句话。以前遇到「有力气」的局面，我的第一反应是确认自己站在哪一边、手里攥着什么牌——那是存在论式的自我认同。而大壮六爻从头到尾问的都是另一件事：同一种刚壮之力，放在这个时位上，该怎么用。力量本身没有善恶，用的方式和时机才决定吉凶。这一层想通之后，「有劲儿」就不再是资格，而变成一道要现场作答的题。</p><p>第二处是**「正」与「贞」的分野**。以前我把这两个字当同义词用，现在分清了：正是天地之道的客观状态，贞是人身处势中时的主观选择。人之所以需要「守」，恰恰因为人有力、有欲、有可仗之势。势越盛，「守」这个动作就越不是多余的客气，而是唯一能让自己不失准的东西。彖传说「正大而天地之情可见矣」——人若能在这时候守住，就和天地同频了。</p><p>第三处是**「用壮」与「用罔」**。九三给我的提醒很具体：不是没有力量，而是有力量却懂得不炫耀、不硬碰。「罔」不是示弱，是不把力气花在不该花的地方。这比初九「壮于趾，征凶」更深一层——初九是急着用，九三是懂得怎么用。</p><p>第四处，也是我读得最慢的一处：<strong>从「角」到「輹」</strong>。九四那一转，力量从「对抗式的冲撞」变成「承载式的运行」。同一个人、同一股劲，一旦落点从「撞开什么」换成「托住什么」，吉就自己来了。这是我这一年最该练的一次转化。</p><p>最后一层是<strong>六五与上六的对照</strong>：六五在还没到顶时就从容卸力（丧羊于易，无悔），上六则一路带着那套已经证明会「羸其角」的老办法冲到了尽头，卡死了才靠「艰」收拾。懂得提前放下，永远比在极限处狼狈补救更高明——敬慎是最后一道保险，而它最好用不上。</p><blockquote><p>力量会说谎，时位不会；与其问「我是谁」，不如问「此刻该怎么做」。</p></blockquote><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：遁（第三十三卦）、晋（第三十五卦）、夬（第四十三卦）</li><li>大壮与遁的连结：大壮是阳盛而进，遁是阴长而退——一进一退，是同一枚硬币的两面。大壮的覆卦（六爻整体颠倒）正是天山遁。</li><li>大壮与晋的连结：序卦「物不可以终壮，故受之以晋」——壮到极处不宜再壮，转而向上进显，故晋卦承接大壮。</li><li>大壮与夬的连结：大壮是势盛而未决，夬是积害既明而果决除之——壮是蓄势，夬是用势。</li></ul>',28))])}}});export{c as __pageData,x as default};
